using System;

public class Program
{
    public static int NodeElement(int[,] mat, int row, int col)
    {
        int r = 0, c = 0;
        for (int j = 0; j < mat.GetLength(1); j++) r += mat[row, j];
        for (int i = 0; i < mat.GetLength(0); i++) c += mat[i, col];
        return r == c ? 1 : 0;
    }

    public static void Main()
