using System;

public class Program
{
    public static int PositiveRow(int[,] arr, int k)
    {
        for (int j = 0; j < arr.GetLength(1); j++)
            if (arr[k, j] <= 0)
                return 0;
        return 1;
    }

    public static int PositiveColomn(int[,] arr, int j)
    {
        for (int i = 0; i < arr.GetLength(0); i++)
            if (arr[i, j] <= 0)
                return 0;
        return 1;
    }

    public static void Main()
    {
        int rows = int.Parse(Console.ReadLine());
        int cols = int.Parse(Console.ReadLine());
        int[,] m = new int[rows, cols];
        for (int i = 0; i < rows; i++)
        {
            string[] parts = Console.ReadLine().Split(' ');
            for (int j = 0; j < cols; j++)
                m[i, j] = int.Parse(parts[j]);
        }
        int pr = 0, pc = 0;
        for (int i = 0; i < rows; i++) pr += PositiveRow(m, i);
        for (int j = 0; j < cols; j++) pc += PositiveColomn(m, j);
        Console.WriteLine(pr > pc ? "yes" : "no");
    }
}
